# Dynamic symbol export map for libphoenix (P2-6).
# Only the public C API is exported; all internal helpers (pool/engine/mapping
# helpers, __phxfs_deregmem, the phxfs_close(phxfs_fileid_t) C++ overload,
# connector globals, etc.) are hidden.
PHOENIX {
  global:
    phxfs_open;
    phxfs_close;
    phxfs_get_page_size;
    phxfs_find_dev;
    phxfs_read;
    phxfs_write;
    phxfs_regmem;
    phxfs_deregmem;
    phxfs_read_batch;
    phxfs_write_batch;
    phxfs_batch_submit_read;
    phxfs_batch_submit_write;
    phxfs_batch_wait;
    phxfs_batch_destroy;
    phxfs_io_engine_name;
  local:
    *;
};
